    ["套装集齐奖励界面领取-九幽血歌异色发"] = "ƩƽậǃǦǉạƾǦƼƾƶǄǦǤƾệǃǦǉƽưởǃƼǦǉƽǊǦǉƽậǅǦđủǦƷộǦ-ǦǥƚƸǦǀƽƑƸǦǂƐǊǦƞửǊǦǕǦƣǊǓếǉǦƞƶ",
    ["购买时装南冥幽梦附赠"] = "ƩƽậǃǦǀƘǂǦǀƽƾǦǂǊƶǦǉƽờƾǦǉǇƶǃƼǦƩƶǂǦƨƾǃƽǦǕǦƨộǃƼ",
    ["商店推荐页-移动端-九幽血歌异色发-男"] = "ǥǇƶǃƼǦđềǦƸửǦƸửƶǦƽƐǃƼǦ-ǦƝảǃǦǤƾǦđộǃƼǦ-ǦǥƚƸǦǀƽƑƸǦǂƐǊǦƞửǊǦǕǦƣǊǓếǉǦƞƶǦ-ǦƩƶǂ",
    ["商店推荐页-九幽血歌异色发-男"] = "ǥǇƶǃƼǦđềǦƸửǦƸửƶǦƽƐǃƼǦ-ǦǥƚƸǦǀƽƑƸǦǂƐǊǦƞửǊǦǕǦƣǊǓếǉǦƞƶǦ-ǦƩƶǂ",
    ["前衣花纹"] = "ƣǄƶǦǋăǃǦƑǄǦǉǇướƸ",
    ["考生可通过#Y传音入密#E，与其他考生合作。通过快速点击传音来传递消息，累积失序值。\n监试官靠近考生后可以发现传音轨迹，后使用#Y金玉手#E制止考生。"] = "ǥƽƓǦǈƾǃƽǦƸƚǦǉƽểǦǉƽƇǃƼǦǆǊƶǦ#YǥǇǊǓềǃǦƀǂǦƩƽậǅǦƨậǉ#EǦđểǦƽợǅǦǉƑƸǦǋớƾǦƸƑƸǦǉƽƓǦǈƾǃƽǦǀƽƑƸ.ǦǥǇǊǓềǃǦǉƾǃǦƷằǃƼǦƸƑƸƽǦǃƽấǃǦǃƽƶǃƽǦǉǇǊǓềǃǦƁǂǦđểǦǉƓƸƽǦǁũǓǦđƾểǂǦƽỗǃǦǁǄạǃ.\nƢƾƑǂǦǉƽƓǦǆǊƶǃǦǀƽƾǦǁạƾǦƼầǃǦǉƽƓǦǈƾǃƽǦƸƚǦǉƽểǦǅƽƑǉǦƽƾệǃǦǆǊỹǦđạǄǦǉǇǊǓềǃǦƁǂ,ǦǈƶǊǦđƚǦǤƖǃƼǦ#YƦƾǂǦƩƼọƸǦǥƽủ#EǦđểǦǃƼăǃǦƸƽặǃǦǉƽƓǦǈƾǃƽ.",
    ["琼枝玉鲸·露华"] = "ƬǊỳǃƽǦƞƽƾǦƩƼọƸǦƦƔǃƽǦ·ǦƧộǦƣǄƶ",
    ["苦读十年，唯求安宁求盛世。\n凝神一笔，不为功名为苍生。"] = "ƦƽổǦƽọƸǦǂườƾǦǃăǂ,ǦƸƽỉǦƸầǊǦƶǃǦǃƾǃƽǦƸầǊǦǉƽịǃƽǦǉƽế.\nƩƼưǃƼǦǉƽầǃǦƽạǦƷƕǉ,ǦǀƽƇǃƼǦǋƔǦƸƇǃƼǦǤƶǃƽǦǋƔǦǉƽươǃƼǦǈƾǃƽ.",
    ["拟练详情"] = "ƞƽƾǦǉƾếǉǦǤƾễǃǦǁǊǓệǃ",
    ["商店推荐页-九幽血歌异色发-女"] = "ǥǇƶǃƼǦđềǦƸửǦƸửƶǦƽƐǃƼǦ-ǦǥƚƸǦǀƽƑƸǦǂƐǊǦƞửǊǦǕǦƣǊǓếǉǦƞƶǦ-ǦƩữ",
    ["前衣右袖"] = "ǥƶǓǦƑǄǦǅƽảƾǦǉǇướƸ",
    ["知乐且知所以乐，此为大智者。\n小八听不懂那些大道理，他只知道，有个游侠夸自己是最聪明的脑壳！"] = "ƝƾếǉǦǋǊƾǦǋƐǦƷƾếǉǦǋƔǦǈƶǄǦǋǊƾ,ǦấǓǦǁƐǦƷậƸǦđạƾǦǉǇƓ.\nǥƾểǊǦƝƑǉǦƸƽẳǃƼǦƽƾểǊǦǂấǓǦđạǄǦǁƈǦǉƽƁǂǦǈƁǊǦđƚ,ǦǃƚǦƸƽỉǦƷƾếǉǦǇằǃƼ,ǦƸƚǦǋịǦǝǊǦƽƾệǅǦǀƽƺǃǦǃƚǦǁƐǦƸƑƾǦđầǊǦǉƽƇǃƼǦǂƾǃƽǦǃƽấǉǦƼƾƶǃǦǉǇầǃ!",
    ["九幽血歌"] = "ƞửǊǦǕǦƣǊǓếǉǦƞƶ",
    ["传南海有琼枝，若银虬玉鲸，自九霄而坠。 及其沉潜，凝琉璃宝髓，聚寒沁冰心。素瓣凌波，清芬入髓，又化万千甘霖天降，凡有陈疾积年者，沾衣而愈；旧伤入骨者，承露俱平。"] = "ǥǇǊǓềǃǦǉƽǊǓếǉǦƩƶǂǦƣảƾǦƸƚǦƬǊỳǃƽǦƞƽƾ,ǦǉựƶǦƩƼƁǃǦƞầǊǦƩƼọƸǦƦƔǃƽ,ǦǉừǦƸƽƓǃǦǉầǃƼǦǂƁǓǦǇơƾǦǍǊốǃƼ.ǦƦƽƾǦƸƽƔǂǦǍǊốǃƼǦđƑǓǦǈƁǊ,ǦǃƼưǃƼǦǉụǦǁưǊǦǁǓǦƷảǄǦǉủǓ,ǦǀếǉǦǉụǦƽƐǃǦǉƽấǂǦƷăǃƼǦǉƁǂ.ǦƞƑǃƽǦǉǇắǃƼǦǁướǉǦǈƚǃƼ,ǦǉƽƶǃƽǦƽươǃƼǦǃƽậǅǦǉủǓ,ǦǁạƾǦƽƚƶǦǋạǃǦǉƽƾƙǃǦƸƶǂǦǁƁǂǦƽạǦǅƽƐǂ,ǦǅƽƐǂǦǁƐǦǀẻǦƸƚǦƷệǃƽǦƸũǦǁƁǊǦǃăǂ,ǦƸƽạǂǦƑǄǦǁƐǦǀƽỏƾ;ǦǉƽươǃƼǦǉƓƸƽǦǋƐǄǦǍươǃƼ,ǦǉƽấǂǦǈươǃƼǦǁƾềǃǦǉƶǃ.",
    ["使用此物，可获得武学“#Y明川药典#E”的“露华”主题绝世外观特效——琼枝玉鲸·露华。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦǉǊǓệǉǦǉƽếǦƸƽủǦđềǦ\"ƧộǦƣǄƶ\"ǦƸủƶǦǋƅǦƽọƸǦ\"#YƨƾǃƽǦƳǊǓƙǃǦǝượƸǦĐƾểǃ#E\"Ǧ—ǦƬǊỳǃƽǦƞƽƾǦƩƼọƸǦƦƔǃƽǦ·ǦƧộǦƣǄƶ.",
    ["裙纱渐变"] = "ƮắƸǦđộǦǋƑǓǦǈƶ",
    ["【南冥幽梦】引，蝶影寄相思"] = "ǝẫǃǦ[ƩƶǂǦƨƾǃƽǦǕǦƨộǃƼ],ǦđƾệǅǦảǃƽǦƼửƾǦǉươǃƼǦǉư",
    ["喜花你"] = "ƣỷǦƣǄƶǦƩƽĩ",
    ["考生可通过#Y看小抄#E，在知识与脑袋重合时进行记忆誊抄，来累积失序值。\n监试官可通过观察考生动作以及小抄，通过#Y金玉手#E制止考生。"] = "ǥƽƓǦǈƾǃƽǦƸƚǦǉƽểǦǉƽƇǃƼǦǆǊƶǦ#YƳƺǂǦǉƐƾǦǁƾệǊ#E,ǦǉƾếǃǦƽƐǃƽǦǈƶǄǦƸƽƗǅǦƼƽƾǦǃƽớǦǀƽƾǦǀƾếǃǦǉƽứƸǦǋƐǦđầǊǦǉǇƖǃƼǦǀƽớǅǦđểǦǉƓƸƽǦǁũǓǦđƾểǂǦƽỗǃǦǁǄạǃ.\nƢƾƑǂǦǉƽƓǦǆǊƶǃǦƸƚǦǉƽểǦǆǊƶǃǦǈƑǉǦđộǃƼǦǉƑƸǦƸủƶǦǉƽƓǦǈƾǃƽǦǋƐǦǉƐƾǦǁƾệǊ,ǦǉƽƇǃƼǦǆǊƶǦ#YƦƾǂǦƩƼọƸǦǥƽủ#EǦđểǦǃƼăǃǦƸƽặǃǦǉƽƓǦǈƾǃƽ.",
    ["「无相金身」奇术特效外观，特惠上架"] = "ƩƼǄạƾǦǆǊƶǃǦƽƾệǊǦứǃƼǦǀỳǦǉƽǊậǉǦ[ƱƇǦǥướǃƼǦƦƾǂǦǥƽƁǃ],ǦǁƙǃǦǀệǦưǊǦđƃƾ",
    ["使用此物，可获得奇术“#Y无相金身#E”的外观特效——知乐而乐。"] = "ƮửǦǤụǃƼǦǋậǉǦǃƐǓ,ǦƸƚǦǉƽểǦǃƽậǃǦđượƸǦƽƾệǊǦứǃƼǦǃƼǄạƾǦǆǊƶǃǦƸủƶǦǀỳǦǉƽǊậǉǦ\"#YƱƇǦǥướǃƼǦƦƾǂǦǥƽƁǃ#E\"Ǧ—ǦǥǇƾǦƧạƸǦƩƽƾǦƧạƸ.",
    ["辞朱颜"] = "ǥừǦƞƽǊǦƩƽƶǃ",
    ["青山·露华"] = "ǥƽƶǃƽǦƮơǃǦ·ǦƧộǦƣǄƶ",
    ["商店推荐页-移动端-九幽血歌-男"] = "ǥǇƶǃƼǦđềǦƸửǦƸửƶǦƽƐǃƼǦ-ǦƝảǃǦǤƾǦđộǃƼǦ-ǦƞửǊǦǕǦƣǊǓếǉǦƞƶǦ-ǦƩƶǂ",
    ["吾有一惑，特来问君。"] = "ǥƶǦƸƚǦǂộǉǦđƾềǊǦǉƽắƸǦǂắƸ,ǦđặƸǦƷƾệǉǦđếǃǦƽỏƾǦǃƼườƾ.",
    ["扔出纸团"] = "ƩƗǂǦƼƾấǓǦǉƽƾ",
    ["「明川药典」武学特效"] = "ƣƾệǊǦứǃƼǦǋƅǦƽọƸǦ[ƨƾǃƽǦƳǊǓƙǃǦǝượƸǦĐƾểǃ]",
    ["传闻世间有异色双蝶，栖于幽冥之畔，游离生死两界。\n以身为引，化作阴阳灵媒，可替逝去之人将未尽的思念捎往人间。"] = "ǥǇǊǓềǃǦǉƽǊǓếǉǦǉƽếǦƼƾƶǃǦƸƚǦđƇƾǦƷướǂǦǀƽƑƸǦǂƐǊ,ǦǉǇƕǦǃƼụǦƷƙǃǦƷờǦǕǦƨƾǃƽ,ǦǤǊǦǃƼǄạǃǦƼƾữƶǦƽƶƾǦƸƅƾǦǈƾǃƽǦǉử.\nƧấǓǦǉƽƁǃǦǁƐǂǦǤẫǃ,ǦƽƚƶǦǉƽƐǃƽǦǁƾǃƽǦǂƇƾǦƁǂǦǤươǃƼ,ǦƸƚǦǉƽểǦǉƽƶǓǦǃƼườƾǦđƃǦǀƽǊấǉǦǂƶǃƼǦǃỗƾǦǃƾềǂǦǉƽươǃƼǦǃƽớǦƸƽưƶǦǉǇọǃǦǋềǦǁạƾǦǃƽƁǃǦƼƾƶǃ.",
    ["一朵小花，左瞧右瞧，总是欢喜，送给最喜欢的你。"] = "ƨộǉǦđƚƶǦƽǄƶǦǃƽỏ,ǦǃƽƔǃǦǉảǦǃƼƚǦƽữǊ,ǦǋẫǃǦǁǊƇǃǦǉƽấǓǦƽǄƶǃǦƽỷ,ǦǍƾǃǦǉặǃƼǦƸƽǄǦǃƼườƾǦǉƶǦǓƙǊǦǆǊƈǦǃƽấǉ.",
    ["全新发型，限时上架。\n相传世有异蝶，日出而生，日暮而死，\n可引生人魂魄渡幽冥之水，令情深不渝者，隔阴阳相会。"] = "ƦƾểǊǦǉƚƸǦƽǄƐǃǦǉǄƐǃǦǂớƾ,ǦǁƙǃǦǀệǦƸƚǦƽạǃǦǂứƸǦǉƽờƾǦƼƾƶǃ.\nǥươǃƼǦǉǇǊǓềǃǦđờƾǦƸƚǦǤịǦđƾệǅ,ǦǂặǉǦǉǇờƾǦǂọƸǦǉƽƔǦǈƾǃƽ,ǦǂặǉǦǉǇờƾǦǁặǃǦǉƽƔǦǉử,\nƸƚǦǉƽểǦǤẫǃǦƽồǃǦǅƽƑƸƽǦǃƼườƾǦǈốǃƼǦǋượǉǦǃướƸǦǕǦƨƾǃƽ,ǦǀƽƾếǃǦǀẻǦǉƔǃƽǦǉƽƁǂǦǀƽƇǃƼǦđổƾǦđượƸǦƼặǅǦǁạƾǦǃƽƶǊǦǃơƾǦƸƑƸƽǦƷƾệǉǦƁǂǦǤươǃƼ.",
    ["手套衣饰"] = "ǥǇƶǃƼǦǈứƸǦƷƶǄǦǉƶǓ",
    ["监试官目标："] = "ƨụƸǦǉƾƙǊǦƢƾƑǂǦǉƽƓǦǆǊƶǃ:",
    ["优先监试官"] = "ƯǊǦǉƾƙǃǦƢƾƑǂǦǉƽƓǦǆǊƶǃ",
    ["袖子里裙"] = "ƱƑǓǦǁƚǉǦǉǇǄǃƼǦốǃƼǦǉƶǓ",
    ["小八金身"] = "ƦƾǂǦǉƽƁǃǦǥƾểǊǦƝƑǉ",
    ["明川·玉鲸"] = "ƨƾǃƽǦƳǊǓƙǃǦ·ǦƩƼọƸǦƦƔǃƽ",
    ["明川药典集齐2个奖励"] = "ǥƽưởǃƼǦǉƽǊǦǉƽậǅǦđủǦ2ǦǂƚǃǦƨƾǃƽǦƳǊǓƙǃǦǝượƸǦĐƾểǃ",
    ["完成监场拟练"] = "ƣǄƐǃǦǉƽƐǃƽǦǝƾễǃǦǁǊǓệǃǦƢƾƑǂǦǉǇườǃƼ",
    ["尽可能的使失序度达到满"] = "ƞốǦƼắǃƼǦƽếǉǦǈứƸǦǀƽƾếǃǦđộǦƽỗǃǦǁǄạǃǦđạǉǦǂứƸǦǉốƾǦđƶ",
