    ["江晚諭"] = "ƢƾƶǃƼǦƱƃǃǦǝụ",
    ["絮歆舒"] = "ƩƽứǦƣƁǂǦǥƽư",
    ["温浮尘"] = "ƆǃǦƫƽƖǦǥǇầǃ",
    ["红糖慕赤"] = "ƣồǃƼǦĐườǃƼǦƨộǦƳƓƸƽ",
    ["沈蛮辞"] = "ǥƽẩǂǦƨƶǃǦǥừ",
    ["晴情君"] = "ǥƔǃƽǦǥƔǃƽǦƬǊƁǃ",
    ["夜名船夫"] = "ǝạǦǝƶǃƽǦǥƽǊǓềǃǦƫƽǊ",
    ["吃我攸巡飞弹"] = "ĂǃǦđạǃǦƷƶǓǦǝǊǦǥǊầǃǦƸủƶǦǉƶ",
    ["浮生墨三季"] = "ƫƽƖǦƮƾǃƽǦƨặƸǦǥƶǂǦƬǊƈ",
